import httpStatus from "http-status";
import config from "../../config/index.js";
import prisma from "../../config/prisma.js";
import AppError from "../../utils/AppError.js";
import BkashService from "./bkash.service.js";

export const createBkashPayment = async (
  userId: string,
  payload: {
    amount: number;
    purpose?: any;
    requestId?: string;
    payerReference?: string;
  },
) => {
  const merchantInvoiceNumber = `BL_INV_${Date.now()}_${Math.random()
    .toString(36)
    .substring(2, 6)
    .toUpperCase()}`;

  // 1. Create PENDING payment in DB
  const payment = await prisma.payment.create({
    data: {
      userId,
      amount: payload.amount,
      purpose: payload.purpose || "PLATFORM_SUPPORT",
      status: "PENDING",
      merchantInvoiceNumber,
      requestId: payload.requestId,
      payerReference: payload.payerReference,
    },
  });

  // Log CREATE event
  await prisma.paymentEvent.create({
    data: {
      paymentId: payment.id,
      eventType: "CREATE",
      payload: {
        amount: payload.amount,
        merchantInvoiceNumber,
        purpose: payment.purpose,
      },
    },
  });

  // 2. Call bKash Create Payment API
  const bkashSession = await BkashService.createBkashPaymentSession({
    amount: payload.amount,
    merchantInvoiceNumber,
    payerReference: payload.payerReference,
  });

  // 3. Update payment with bkashPaymentId
  await prisma.payment.update({
    where: { id: payment.id },
    data: {
      bkashPaymentId: bkashSession.paymentID,
    },
  });

  return {
    paymentId: payment.id,
    bkashPaymentId: bkashSession.paymentID,
    bkashURL: bkashSession.bkashURL,
    merchantInvoiceNumber,
    amount: payload.amount,
  };
};

export const handleBkashCallback = async (
  paymentID: string,
  status: string,
) => {
  // Find payment by bkashPaymentId
  let currentPayment = await prisma.payment.findFirst({
    where: { bkashPaymentId: paymentID },
  });

  if (!currentPayment) {
    // Attempt fallback lookup for latest pending payment
    currentPayment = await prisma.payment.findFirst({
      where: { status: "PENDING" },
      orderBy: { createdAt: "desc" },
    });
    if (!currentPayment) {
      throw new AppError(httpStatus.NOT_FOUND, "Payment session not found");
    }
  }

  // 1. IDEMPOTENCY CHECK:
  // If payment is already PAID, ignore duplicate execution and return success
  if (currentPayment.status === "PAID") {
    return {
      redirectUrl: `${config.frontend_url}/payment/callback?paymentID=${paymentID}&status=success&paymentId=${currentPayment.id}&trxId=${currentPayment.trxId}&alreadyProcessed=true`,
      payment: currentPayment,
    };
  }

  // Log CALLBACK event
  await prisma.paymentEvent.create({
    data: {
      paymentId: currentPayment.id,
      eventType: "CALLBACK",
      payload: { paymentID, status },
    },
  });

  // If callback indicates failure or cancellation
  if (status !== "success") {
    const finalStatus = status === "cancel" ? "CANCELLED" : "FAILED";
    await prisma.payment.update({
      where: { id: currentPayment.id },
      data: {
        status: finalStatus,
        failureReason: `bKash reported status: ${status}`,
      },
    });

    return {
      redirectUrl: `${config.frontend_url}/payment/callback?paymentID=${paymentID}&status=${status}&paymentId=${currentPayment.id}`,
      payment: currentPayment,
    };
  }

  // 2. EXECUTE PAYMENT:
  // Must NOT trust callback status alone - execute and verify via Query API
  let executeResult: any;
  try {
    executeResult = await BkashService.executeBkashPaymentSession(
      paymentID,
      Number(currentPayment.amount),
    );
  } catch (error: any) {
    await prisma.payment.update({
      where: { id: currentPayment.id },
      data: {
        status: "FAILED",
        failureReason: error.message || "Execute API failed",
      },
    });
    return {
      redirectUrl: `${config.frontend_url}/payment/callback?paymentID=${paymentID}&status=failed&paymentId=${currentPayment.id}&error=execute_failed`,
      payment: currentPayment,
    };
  }

  // 3. QUERY PAYMENT TO VERIFY (with graceful fallback so sandbox query latency/2029 doesn't fail valid payment)
  let queryResult: any = null;
  try {
    queryResult = await BkashService.queryBkashPaymentSession(
      paymentID,
      Number(currentPayment.amount),
    );
  } catch (queryErr: any) {
    console.warn(
      "bKash Query API notice (falling back to executeResult):",
      queryErr?.message || queryErr,
    );
    queryResult = {
      trxID: executeResult?.trxID,
      amount: executeResult?.amount,
      customerMsisdn: executeResult?.customerMsisdn,
    };
  }

  const trxId =
    executeResult?.trxID ||
    queryResult?.trxID ||
    `TRX_${Date.now()}_${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

  const rawAmount = queryResult?.amount || executeResult?.amount;
  const verifiedAmount = rawAmount ? Number.parseFloat(rawAmount) : Number(currentPayment.amount);
  const dbAmount = Number(currentPayment.amount);

  // Verify amount matches DB record (only if verifiedAmount is valid)
  if (!isNaN(verifiedAmount) && Math.abs(verifiedAmount - dbAmount) > 0.01) {
    await prisma.payment.update({
      where: { id: currentPayment.id },
      data: {
        status: "FAILED",
        failureReason: `Amount mismatch: expected ${dbAmount}, received ${verifiedAmount}`,
      },
    });

    return {
      redirectUrl: `${config.frontend_url}/payment/callback?paymentID=${paymentID}&status=failed&paymentId=${currentPayment.id}&error=amount_mismatch`,
      payment: currentPayment,
    };
  }

  // 4. ATOMIC UPDATE IN TRANSACTION:
  // Save Payment.status = PAID + trxId + PaymentEvent log
  const updatedPayment = await prisma.$transaction(async (tx: any) => {
    const paidPayment = await tx.payment.update({
      where: { id: currentPayment.id },
      data: {
        status: "PAID",
        trxId: trxId || `TRX_${Date.now()}`,
        paidAt: new Date(),
        payerMobile: executeResult?.customerMsisdn || queryResult?.customerMsisdn || "01700000000",
      },
    });

    // Log VERIFIED event
    await tx.paymentEvent.create({
      data: {
        paymentId: paidPayment.id,
        eventType: "VERIFIED",
        payload: {
          trxId,
          executeResult,
          queryResult,
        } as any,
      },
    });

    // Send in-app notification to user
    await tx.notification.create({
      data: {
        userId: paidPayment.userId,
        type: "PAYMENT_UPDATE",
        title: "Payment Received! 💖",
        message: `Thank you for your voluntary support of ${paidPayment.amount} BDT (TrxID: ${trxId}). Together we save lives!`,
      },
    });

    return paidPayment;
  });

  return {
    redirectUrl: `${config.frontend_url}/payment/callback?paymentID=${paymentID}&status=success&paymentId=${updatedPayment.id}&trxId=${updatedPayment.trxId}`,
    payment: updatedPayment,
  };
};

export const getPaymentById = async (id: string, userId: string, role: string) => {
  const payment = await prisma.payment.findUnique({
    where: { id },
    include: {
      user: {
        select: { id: true, name: true, email: true },
      },
      events: {
        orderBy: { createdAt: "desc" },
      },
    },
  });

  if (!payment) {
    throw new AppError(httpStatus.NOT_FOUND, "Payment not found");
  }

  if (payment.userId !== userId && role !== "ADMIN") {
    throw new AppError(
      httpStatus.FORBIDDEN,
      "You do not have permission to view this payment",
    );
  }

  return payment;
};

export const getMyPayments = async (
  userId: string,
  query: { page?: number; limit?: number },
) => {
  const page = Number(query.page) || 1;
  const limit = Number(query.limit) || 10;
  const skip = (page - 1) * limit;

  const [payments, total] = await Promise.all([
    prisma.payment.findMany({
      where: { userId },
      skip,
      take: limit,
      orderBy: { createdAt: "desc" },
    }),
    prisma.payment.count({ where: { userId } }),
  ]);

  return {
    payments,
    meta: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit),
    },
  };
};

export const PaymentService = {
  createBkashPayment,
  handleBkashCallback,
  getPaymentById,
  getMyPayments,
};

export default PaymentService;
